"""Full GBV draft-catalogue map; internal contract, not a live ParaLearn exam."""
import json
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from schools.exam_blueprints import validate_blueprint

def blueprint():
    codes=[f"SWP-{n:03}" for n in range(49,57)]
    items=[dict(id=f"GBV8-{code}-MCQ-{n:02}",type="MCQ",marks=1,course_codes=[code],question_binding=None)
        for code in codes for n in range(1,6)]
    short=[
        (codes[:2],"A fictional service requires partner approval for adult access. An adult privately asks for help without wanting to recount an incident. Give five elements of an appropriate power-aware first response.",
         "Identify the access rule and its effect on independent choice without stereotyping; listen without investigation or requiring a disclosure narrative; explain role and confidentiality limits honestly; respect the adult's preferences and consent rather than impose a referral; and identify a verified suitable support option with an agreed safe next contact. Context never excuses violence or transfers responsibility to the survivor.",
         ["Gender power and access without stereotype (049)","Listening without investigation or forced disclosure (050)","Role and privacy limits (050)","Choice consent and non-coercion (049/050)","Verified support and safe next step (050)"]),
        (codes[2:4],"A fictional adult has accepted discussion of support but is overwhelmed by repeated retelling and an unverified referral. Give five corrections for a supervised support and coordination outline.",
         "Retain person-led goals and revisit preferences; plan safety and contact within qualified supervision rather than promise protection; minimise repeated retelling and information shared for each consented purpose; verify service scope and capacity before a bounded referral; and agree follow-up responsibilities with trauma-informed choice, predictable communication and clinical limits. No diagnosis, therapy or unsupervised casework is authorised.",
         ["Person-led goals and revisitable preferences (051/052)","Supervised planning and realistic safety limits (051)","Consent and minimum information/retelling (051/052)","Verified referral and coordination roles (051/052)","Trauma-informed follow-up without clinical overreach (052)"]),
        ([codes[4]],"A fictional club holds three awareness sessions and reports changed views. Its organiser claims proven violence reduction. Give five requirements for a defensible prevention review.",
         "Distinguish private attitudes, perceived social expectations and behaviour; state a plausible mechanism rather than a proven effect; separate session outputs and stated views from violence outcomes; examine participation, context, alternative explanations and possible harms within approved arrangements; and assign a feasible revision and review owner. Pooled trial effects cannot be promised locally.",
         ["Attitude expectation behaviour distinction","Theory-of-change status","Output and outcome distinction","Coverage alternatives and harms","Accountable bounded revision"]),
        ([codes[5]],"A non-graphic fictional concern involves a girl leaving school for marriage. A proposed plan assumes the accompanying adult is safe and promises an educational meeting will end FGM. Give five corrections.",
         "Use qualified child safeguarding with attention to best interests, evolving capacities and age-appropriate participation; distinguish assent from legal consent and avoid assuming caregiver safety; obtain appropriate local legal/professional decisions instead of universal reporting or validity claims; preserve non-stigmatising access to qualified services without medicalisation or investigation; and distinguish very low-certainty knowledge/attitude evidence from demonstrated FGM incidence reduction.",
         ["Best interests evolving capacities and participation","Assent consent and caregiver safety","Qualified local safeguarding/legal authority","Dignified qualified access and scope","FGM evidence certainty and outcome limits"]),
        ([codes[6]],"A fictional adult reports technology-related threats but needs a shared device for work. Someone proposes immediate deletion, a private screenshot in coursework and email follow-up without agreement. Give five corrections.",
         "Recognise digital/offline coercion and access needs without blame; distinguish reports from technical verification rather than diagnose spyware; agree safe contact before sensitive messages; consider person-led priorities and qualified specialist planning before deletion/reporting; and exclude credentials or intimate/identifying material from coursework while respecting purpose-specific information limits. No forensic access or guaranteed platform outcome.",
         ["Digital/offline context and access","Evidence status and diagnostic boundary","Agreed safe contact","Specialist planning before changes","No sensitive coursework material or unapproved reuse"]),
        ([codes[7]],"A fictional service completes twelve of thirty eligible referrals in period A and eighteen of sixty in B. It merges clinical and casework records for a sponsor and claims a higher completion rate proves lower GBV prevalence. Give five corrections.",
         "Calculate A as forty percent and B as thirty percent, a decrease of ten percentage points despite a higher count; define units, denominators, periods and missingness; distinguish service use from prevalence and avoid causal claims; separate clinical/casework purposes with minimisation and qualified consent/governance before sharing; and use an authorised relevant review with safe feedback, suitable measures and a responsible action owner.",
         ["Correct 40% 30% and ten-percentage-point decrease","Definitions comparability and missingness","Service prevalence and causal limits","Purpose minimisation and qualified governance","Suitable ethical review and accountable response"]),
    ]
    for n,(coverage,prompt,model,criteria) in enumerate(short,1):
        items.append(dict(id=f"GBV8-SA-{n:02}",type="SHORT_ANSWER",marks=5,course_codes=coverage,prompt=prompt,model_answer=model,
            rubric=[dict(criterion=x,marks=1) for x in criteria],human_marking_required=True))
    essays=[
        ("Develop a bounded support and prevention proposal for a fictional youth/community service. Adults face partner-approval barriers; an adolescent raises a non-graphic marriage concern; digital threats affect access to work; and a sponsor requests linked health/casework data. Integrate all eight GBV courses, explaining support roles, consent and child-specific safeguarding, prevention mechanisms, safe digital planning and a feasible review. State authority, dependencies and evidence limits.",
         "Credit coherent reasoning across all eight courses: analyse power and intersecting access without blame; provide respectful non-investigative first response; use person-led supervised casework/referral planning with trauma-informed choice and qualified clinical boundaries; distinguish prevention assumptions from effects; use child-specific best interests, consent/assent and local safeguarding expertise with honest FGM evidence limits; preserve safe contact and specialist digital planning without sensitive material; and minimise purpose-specific information, define indicators and bound evaluation claims. An introductory course does not qualify a specialist. Accept equivalent defensible reasoning, not source wording.",
         ["Power and survivor-centred first response (049/050)","Supervised casework trauma-informed coordination and follow-up (051/052)","Prevention mechanisms and child/FGM safeguarding evidence (053/054)","Safe digital contact specialist planning and information boundaries (055)","Data governance evaluation limits authority and response (056)"]),
        ("Critique a fictional programme claiming success from attendance, public pledges, platform reports and increased referral counts. It asks learners for survivor testimony, assumes a caregiver is safe, treats battery loss as spyware, copies a foreign questionnaire and sends full records across co-located services. Write a justified corrective plan across all eight courses. Use the fictional change from twelve of thirty to eighteen of sixty referrals where relevant.",
         "A strong critique connects unequal power and coercion with first-response choice; replaces forced testimony, repeated retelling and unsupported casework with supervised person-led support; separates sessions/pledges from violence outcomes and applies child-specific safeguarding and very low-certainty FGM evidence carefully; rejects diagnosis by device symptom, unsafe messages, blanket resets and platform guarantees; and separates clinical/case purposes, reviews instrument fit/permissions, calculates forty percent to thirty percent correctly and avoids prevalence or causal recovery claims. Identify qualified owners, resources, feedback and review rather than collect more private information.",
         ["Power coercion and non-investigative support (049/050)","Supervised safety planning trauma-informed coordination (051/052)","Prevention outcome distinctions child safeguarding and evidence (053/054)","Digital evidence status safe contact and specialist roles (055)","Purpose consent correct arithmetic measurement and accountable evaluation (056)"]),
    ]
    for n,(prompt,model,criteria) in enumerate(essays,1):
        items.append(dict(id=f"GBV8-ESSAY-{n:02}",type="ESSAY",marks=15,course_codes=codes,prompt=prompt,model_answer=model,
            rubric=[dict(criterion=x,marks=3,scoring="0 absent/unsafe; 1 relevant limited point; 2 defensible reasoning with important omission; 3 coherent contextual reasoning with feasible action and evidence limits.") for x in criteria],human_marking_required=True))
    return dict(status="draft_for_review",school_code="GBV",curriculum_version="GBV-proposed-eight-course-0.1.0",
        provider="ParaLearn CBT",provider_assessment_id=None,provider_contract_verified=False,required_courses=codes,
        programme_target_course_count=8,draft_catalogue_complete=True,curriculum_complete=False,remaining_curriculum_titles=[],
        scope_note="All eight proposed GBV courses represented as review drafts, not an approved professional curriculum. Historical four-course scope plan retained. Specialist safeguarding, Nigerian practice/legal, accessibility, piloting, supervised skills, independent academic approval, live ParaLearn mixed-item support and question binding remain pending. This file cannot launch an exam or authorise a certificate.",
        proposed_duration_minutes=210,duration_status="Proposed; academic review, accessibility adjustments and learner piloting required",
        marking_policy=dict(proposed_pass_percent=70,moderation_required=True,ai_only_finalisation=False,
            rubric_rule="Human marking with criterion-level rationales and independent human moderation. Accept equivalent defensible reasoning. Refer unsafe reasoning for specialist review; this draft defines no unapproved automatic fail or professional competency standard.",
            appeals="Preserve responses, rubric version, marker, moderation and amendment history with an authorised appeal route."),
        certification=dict(authorised=False,requirements=["Complete all eight approved GBV courses and verified ParaLearn course CBT passes before a course badge is awarded","Pass the final full-curriculum ParaLearn exam after human written marking and moderation","Meet approved curriculum/supervised skills requirements and receive authorised signatories; Head of Learning name/signature pending; Founder, SWEEP Academy - Prof. Mina Ogbanga"]),items=items)

if __name__=="__main__":
    data=blueprint();print(validate_blueprint(data))
    (ROOT/"production_courseware/phase_eight/gbv_batch_02/school_exam_blueprint.json").write_text(json.dumps(data,indent=2)+"\n",encoding="utf-8")
